package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	n, _ := strconv.Atoi(strings.Fields(sc.Text())[0])
	sc.Scan()
	fields := strings.Fields(sc.Text())
	a := make([]int, n)
	for i := range n {
		a[i], _ = strconv.Atoi(fields[i])
	}

	// ここから下を書く: b := a としてから b[0] を 10 倍し、
	// a と b を 1 行ずつ fmt.Println で出力する
	_ = a
	_ = fmt.Println
}

